/* @autogenerated */
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { SnippetRepository } from 'app/features/template/snippet/repository/snippet-repository.service';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import { SnippetAsset } from 'app/features/template/snippet-asset/model/snippet-asset.model';
import { SnippetAssetRepository } from 'app/features/template/snippet-asset/repository/snippet-asset-repository.service';
import { Component, inject } from '@angular/core';
import {
  SNIPPET_ASSET_EXCEL_SENSITIVE,
  SNIPPET_ASSET_EXCEL_COLUMNS,
} from 'app/features/template/snippet-asset/model/snippet-asset-excel-columns';

@Component({
  selector: 'snippet-asset-view-export-action',
  standalone: false,
  templateUrl: './snippet-asset-view-export-action.component.html',
})
export class SnippetAssetViewExportActionComponent extends BaseExportAction<SnippetAsset> {
  protected readonly scope = 'template/snippet-asset';
  protected readonly repository = inject(SnippetAssetRepository);
  private readonly snippetRepository = inject(SnippetRepository);

  readonly definition: ExportDefinition<SnippetAsset> = {
    name: 'template.snippet-asset',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: SNIPPET_ASSET_EXCEL_COLUMNS,
    sensitive: SNIPPET_ASSET_EXCEL_SENSITIVE,
    references: {
      snippet: {
        names: (refs) =>
          this.snippetRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.code ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
